package com.campusconnect.controller;
import com.campusconnect.model.Student; import com.campusconnect.service.StudentService; import com.campusconnect.util.SessionManager; import javafx.fxml.FXML; import javafx.scene.control.*;
public class StudentDashboardController { @FXML private Label welcomeLabel,profileLabel; @FXML private Button logoutButton; @FXML private void initialize(){Student s=new StudentService().profile(SessionManager.getUser().getId());welcomeLabel.setText("Welcome back, "+(s==null?SessionManager.getUser().getEmail():s.getName())+" 👋");profileLabel.setText(s==null?"Student profile unavailable":s.getStudentId()+" • "+s.getDepartment()+" • Semester "+s.getSemester()+" • "+s.getHostelRoom());}
 @FXML private void complaints(){UiUtil.scene(logoutButton,"complaints.fxml");} @FXML private void lostFound(){UiUtil.scene(logoutButton,"lost-found.fxml");} @FXML private void events(){UiUtil.scene(logoutButton,"events.fxml");} @FXML private void logout(){SessionManager.logout();UiUtil.scene(logoutButton,"login.fxml");} }
